// ─── File: CoordinationStylesDemo.java ───
// Runnable demo: choreography (emergent, event-driven) vs orchestration (central control).

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class CoordinationStylesDemo {

    private static final Logger log = Logger.getLogger("coordination");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrderService order = new OrderService();
        InventoryService inventory = new InventoryService();
        PaymentService payment = new PaymentService();

        log.info("===== CHOREOGRAPHY: services react to events, no central brain =====");
        ChoreographyFlow choreo = new ChoreographyFlow(order, inventory, payment);
        choreo.start("SAV2001");   // emergent flow via events

        log.info("===== ORCHESTRATION: central orchestrator drives each step =====");
        OrderOrchestrator orchestrator = new OrderOrchestrator(order, inventory, payment);
        orchestrator.placeOrder("SAV2001", false);  // success
        orchestrator.placeOrder("SAV2001", true);   // payment fails → central compensation
    }
}

