class WorkflowEvent {
    final String type; final String orderId;
    WorkflowEvent(String type, String orderId) { this.type = type; this.orderId = orderId; }
}

// ─── service/OrderService.java ───
class OrderService {
    private static final Logger log = Logger.getLogger("coordination");
    String create(String account) {
        String id = "ORD-" + UUID.randomUUID().toString().substring(0, 6);
        log.info(() -> "[ORDER] created " + id);
        return id;
    }
    void cancel(String id) { log.warning(() -> "[ORDER] compensate cancel " + id); }
}

