class InventoryService {
    private static final Logger log = Logger.getLogger("coordination");
    void reserve(String id) { log.info(() -> "[INVENTORY] reserved for " + id); }
    void release(String id) { log.warning(() -> "[INVENTORY] compensate release for " + id); }
}

