class PaymentService {
    private static final Logger log = Logger.getLogger("coordination");
    void charge(String id, boolean fail) {
        if (fail) { log.severe(() -> "[PAYMENT] FAILED for " + id); throw new RuntimeException("declined"); }
        log.info(() -> "[PAYMENT] charged " + id);
    }
}

// ─── choreography/EventBus.java ───
class EventBus {
    private final List<Consumer<WorkflowEvent>> subs = new ArrayList<>();
    void subscribe(Consumer<WorkflowEvent> s) { subs.add(s); }
    void publish(WorkflowEvent e) { subs.forEach(s -> s.accept(e)); }
}

// ─── choreography/ChoreographyFlow.java — NO central coordinator ───
class ChoreographyFlow {
    private static final Logger log = Logger.getLogger("coordination");
    private final OrderService order; private final InventoryService inventory; private final PaymentService payment;
    private final EventBus bus = new EventBus();
    ChoreographyFlow(OrderService order, InventoryService inventory, PaymentService payment) {
        this.order = order; this.inventory = inventory; this.payment = payment;
        // Each service reacts to the PREVIOUS service's event — emergent flow.
        bus.subscribe(this::onEvent);
    }
    void start(String account) {
        String id = order.create(account);
        bus.publish(new WorkflowEvent("OrderCreated", id));   // kick off the chain
    }
    private void onEvent(WorkflowEvent e) {
        switch (e.type) {
            case "OrderCreated" -> { inventory.reserve(e.orderId); bus.publish(new WorkflowEvent("StockReserved", e.orderId)); }
            case "StockReserved" -> { payment.charge(e.orderId, false); bus.publish(new WorkflowEvent("Paid", e.orderId)); }
            case "Paid" -> log.info(() -> "[CHOREO] flow done for " + e.orderId
                    + " (no component ever held the full state)");
            default -> { }
        }
    }
}

// ─── orchestration/OrderOrchestrator.java — central brain + state machine ───
class OrderOrchestrator {
    private static final Logger log = Logger.getLogger("coordination");
    private final OrderService order; private final InventoryService inventory; private final PaymentService payment;
    OrderOrchestrator(OrderService order, InventoryService inventory, PaymentService payment) {
        this.order = order; this.inventory = inventory; this.payment = payment;
    }
    void placeOrder(String account, boolean paymentFails) {
        String id = order.create(account);
        String state = "ORDER_CREATED"; log.fine("[ORCH] state=" + state);
        try {
            inventory.reserve(id); state = "STOCK_RESERVED"; log.fine("[ORCH] state=" + state);
            payment.charge(id, paymentFails); state = "PAID"; log.fine("[ORCH] state=" + state);
            log.info(() -> "[ORCH] " + id + " COMPLETED (orchestrator tracked every step)");
            // Hybrid: simple independent fan-out via choreography after PAID.
            log.info(() -> "[CHOREO fan-out] notify + statement + analytics react to Paid independently");
        } catch (RuntimeException ex) {
            log.severe(() -> "[ORCH] failure → central compensation in order");
            inventory.release(id);   // orchestrator owns compensation order
            order.cancel(id);
        }
    }
}

